	MAKE_TEST('_set_c_u64'),
	MAKE_TEST('_set_c_u32')
]
```

Execute the following:
`emcc --bind --emrun -s WASM=1 --std=c++11 --post-js test.js -o index.html test.cpp`
`emrun index.html`

Results: 
* `RuntimeError: integer result unrepresentable` for calls to `set_bind_u32`
* Both `_set_c_u32` and `_set_c_u64` function correctly in both WASM and non-WASM builds.
* `set_bind_u32` works correctly for non-WASM builds.
* Additionally `set_bind_u64` fails with binding error in all versions.

Previously known to work with the following revisions:
emscripten/incoming: `e6e11c01709f082c7a6f7ed1d46c004ad7011c2f`
binaryen/master: `d6508e1f9cef33c43016e4da7dd4b94392f280a9`

comments:
[pepyakin]: It seems like f64-rem is asm2wasm binaryen stuff.

Invoking `emcc` with `-s "BINARYEN=1"` produces following (minimized) asm.js:

```javascript
function () {
  "almost asm";

  var STACKTOP = 0, STACK_MAX = 0;
  var Math_fround=global.Math.fround;

  function _foo($0,$1) {
    $0 = Math_fround($0);
    $1 = Math_fround($1);
    var $2 = Math_fround(0), label = 0, sp = 0;
    sp = STACKTOP;
    $2 = Math_fround($0 % $1);
    return (Math_fround($2));
  }
  return { _foo: _foo };
}
```

`asm2wasm` chocking with this input:

```                                                                                                                                   
[wasm-validator error in function $_foo] 3 != 4: call param types must match, on
[f64] (call $f64-rem
 [f32] (get_local $0)
 [f32] (get_local $1)
)
(on argument 0)
[wasm-validator error in function $_foo] 3 != 4: call param types must match, on
[f64] (call $f64-rem
 [f32] (get_local $0)
 [f32] (get_local $1)
)
(on argument 1)
(module
 (type $FUNCSIG$ddd (func (param f64 f64) (result f64)))
 (import "asm2wasm" "f64-rem" (func $f64-rem (param f64 f64) (result f64)))
 (import "env" "memory" (memory $0 256 256))
 (import "env" "table" (table 0 0 anyfunc))
 (import "env" "memoryBase" (global $memoryBase i32))
 (import "env" "tableBase" (global $tableBase i32))
 (global $STACKTOP (mut i32) (i32.const 0))
 (global $STACK_MAX (mut i32) (i32.const 0))
 (export "_foo" (func $legalstub$_foo))
 (func $_foo (param $$0 f32) (param $$1 f32) (result f32)
  (local $$2 f32)
  (local $label i32)
  (local $sp i32)
  (set_local $sp
   (get_global $STACKTOP)
  )
  (set_local $$2
   (f32.demote/f64
    (call $f64-rem
     (get_local $$0)
     (get_local $$1)
    )
   )
  )
  (return
   (get_local $$2)
  )
 )
 (func $legalstub$_foo (param $0 f64) (param $1 f64) (result f64)
  (f64.promote/f32
   (call $_foo
    (f32.demote/f64
     (get_local $0)
    )
    (f32.demote/f64
     (get_local $1)
    )
   )
  )
 )
)
```

When used without binaryen, emscripten produces asm.js like following (minimized):

```javascript
function () {
  "almost asm";

  var STACKTOP = 0, STACK_MAX = 0;
  var Math_fround=global.Math.fround;

  function _foo($0,$1) {
   $0 = +$0;
   $1 = +$1;
   var $2 = 0.0, label = 0, sp = 0;
   sp = STACKTOP;
   $2 = $0 % $1;
   return (+$2);
  }

  return { _foo: _foo };
}
```

which compiles down to nice webassembly:

```
(module
 (type $FUNCSIG$ddd (func (param f64 f64) (result f64)))
 (import "asm2wasm" "f64-rem" (func $f64-rem (param f64 f64) (result f64)))
 (import "env" "memory" (memory $0 256 256))
 (import "env" "table" (table 0 0 anyfunc))
 (import "env" "memoryBase" (global $memoryBase i32))
 (import "env" "tableBase" (global $tableBase i32))
 (global $STACKTOP (mut i32) (i32.const 0))
 (global $STACK_MAX (mut i32) (i32.const 0))
 (export "_foo" (func $_foo))
 (func $_foo (param $$0 f64) (param $$1 f64) (result f64)
  (local $$2 f64)
  (local $label i32)
  (local $sp i32)
  (set_local $sp
   (get_global $STACKTOP)
  )
  (set_local $$2
   (call $f64-rem
    (get_local $$0)
    (get_local $$1)
   )
  )
  (return
   (get_local $$2)
  )
 )
)
```

I'm not an expert in emscripten/binaryen thing, but I tend to think binaryen is actual culprit here.

---

[kripken]: Should be fixed by that binaryen PR.

[juj]: Commented about this in detail in the PR. Indeed the current behavior blocks on interacting with input on other DOM elements, and generally people have solved this by using the HTML5 Input API, where this is designed to be controllable per event. GLUT/GLFW/SDL each have defaulted to more or less assuming that the only interesting element on the page is the canvas, which has dedicated focus, since that helps most projects get going.

Smarter heuristics are definitely welcome, but we should be careful not to get into a "whose use case is the most important one to be the default?" debate. Perhaps some Emscripten-specific configuration options for GLUT/GLFW/SDL APIs might be in order?

---

[ghost]: @juj Do you mind linking to some documentation about the HTML5 Input API? I'm afraid I don't know which API you're talking about, nor can I find it on Google. Is it the same as `addEventListener`/`removeEventListener`?

Are you sure that smarter heuristics are really a worthwhile solution here (read: even more uncontrollable magic code)? What do you think about a configuration option that ties the existing functionality to just the canvas so that everyone can have their own desired level of control?

```
var myModule = Module({
    attachGLFWEventsToCanvas: true
});
```
library_glfw.js, `glfwInit()`:

```
...
var eventTarget = window;
if(Module['attachGLFWEventsToCanvas']) eventTarget = Module['canvas'];
eventTarget.addEventListener("keydown", GLFW.onKeydown, true);
eventTarget.addEventListener("keypress", GLFW.onKeyPress, true);
eventTarget.addEventListener("keyup", GLFW.onKeyup, true);
eventTarget.addEventListener("blur", GLFW.onBlur, true);
...
```

---

[juj]: > @juj Do you mind linking to some documentation about the HTML5 Input API? I'm afraid I don't know which API you're talking about, nor can I find it on Google. Is it the same as addEventListener/removeEventListener?

The API I'm referring to is the file `#include <emscripten/html5.h>`. See http://kripken.github.io/emscripten-site/docs/api_reference/html5.h.html and https://github.com/kripken/emscripten/blob/incoming/system/include/emscripten/html5.h .

> Are you sure that smarter heuristics are really a worthwhile solution here (read: even more uncontrollable magic code)? What do you think about a configuration option that ties the existing functionality to just the canvas so that everyone can have their own desired level of control?

Hmm, does that work? If one listens on `blur` on the `canvas` rather than `window`, does that come through? I wonder if having an option to choose to listen on all events on either `window` vs `canvas` is enough?

---

[ghost]: same + 1. Glfw event listener (  event.preventDefault() for backspace and tab ) makes inputs unusable.

body:
Hey,
I'm using the emscripten fetch API and it looks like that the memory for each downloaded file is never released. In order to have a reproducible example, I boiled it down to a minimal example,
where files with the following urls are downloaded:

http://localhost/data/1.bin
http://localhost/data/2.bin
...
http://localhost/data/2047.bin

Even if one waits for half an hour, the memory is not released. The sample example written
in JavaScript with XHR request does not have this issue.
Am I doing something wrong?
Thanks for any help. 

```cpp
// compiled with: emcc -s FETCH=1 main.cpp -o index.html
#include <emscripten/fetch.h>

#include <cstdio>
#include <cstring>
#include <vector>
#include <string>

const std::size_t NUM = 2048;
const std::string baseURL = "http://localhost/data/";

void fetchData(std::string url, int fileIdx);

void downloadSucceeded(emscripten_fetch_t *fetch)
{
    printf("Received '%s'\n", fetch->url);

    int fileIdx = int(fetch->userData) + 1;
    emscripten_fetch_close(fetch); // Free data associated with the fetch.

    if(fileIdx < NUM)
        fetchData(baseURL + std::to_string(fileIdx) + ".bin", fileIdx);
}

void downloadFailed(emscripten_fetch_t *fetch)
{
  printf("[ERROR]: %s FAILED!!!\n", fetch->url);
  emscripten_fetch_close(fetch);
}


void fetchData(std::string url, int fileIdx)
{
    emscripten_fetch_attr_t attr;
    emscripten_fetch_attr_init(&attr);
    std::strcpy(attr.requestMethod, "GET");
    attr.attributes = EMSCRIPTEN_FETCH_LOAD_TO_MEMORY;
    attr.onsuccess = downloadSucceeded;
    attr.onerror = downloadFailed;
    attr.userData = (void*)fileIdx;
    emscripten_fetch(&attr, url.c_str());
}

int main()
{
    printf("Start...\n");
    fetchData(baseURL + "1.bin", 1);

    return 0;
}
```

comments:
[kripken]: The [trap mode might be an issue](https://github.com/kripken/emscripten/wiki/WebAssembly#trap-mode). Does building with `-s "BINARYEN_TRAP_MODE='js'"` fix things?

---

[curiousdannii]: I tried all trap modes, no difference.

I made a cut down test case, but it doesn't show any problematic behaviour. I'll keep digging.

<details><summary>Test case</summary><p>

Compile with

```
emcc -s WASM=1 sinftest.c -s EMTERPRETIFY=1 -s EMTERPRETIFY_WHITELIST='["_main"]' -O0
```

```
#include "emscripten.h"
#include <stdint.h>
#include <math.h>

typedef uint32_t glui32;
typedef int32_t glsi32;
typedef float gfloat32;

extern glui32 encode_float(gfloat32 val);
extern gfloat32 decode_float(glui32 val);

glui32 encode_float(gfloat32 val)
{
    glui32 res;
    *(gfloat32 *)(&res) = val;
    return res;
}

gfloat32 decode_float(glui32 val)
{
    gfloat32 res;
    *(glui32 *)(&res) = val;
    return res;
}

int main(void)
{
    glui32 a = 0x3F060A92;
    gfloat32 b = decode_float( a );
    emscripten_log( EM_LOG_CONSOLE, "Decoded float b: %f", b );
    gfloat32 c = sinf( b );
    emscripten_log( EM_LOG_CONSOLE, "sinf(b): %g", c );
    glui32 d = encode_float( c );
    emscripten_log( EM_LOG_CONSOLE, "Encoded uint d: %x", d );

    gfloat32 valf1 = decode_float( 0x3F000000 ) - decode_float( d );
    gfloat32 e = decode_float( 0x33800000 );
    gfloat32 valf2 = fabs( e );
    emscripten_log( EM_LOG_CONSOLE, "valf1: %g e: %g valf2: %g", valf1, e, valf2 );
    glui32 val0 = (valf1 <= valf2 && valf1 >= -valf2);
    emscripten_log( EM_LOG_CONSOLE, "Test result: %d", val0 );
}
```

</p></details>

---

[curiousdannii]: After adding some emscripten_log lines, it definitely seems to be the core `sinf`, `cosf` functions themselves. They aren't returning anything other than `0`, `-0`, `1` (for `cosf`) and `NaN`.

OKAY! PROGRESS. The test case needs EMTERPRETIFY_ASYNC too:

```
#include "emscripten.h"
#include <stdint.h>
#include <math.h>

typedef uint32_t glui32;
typedef float gfloat32;

gfloat32 decode_float(glui32 val);

gfloat32 decode_float(glui32 val)
{
    gfloat32 res;
    *(glui32 *)(&res) = val;
    return res;
}

int main(void)
{
    emscripten_sleep(10);
    glui32 a = 0x3F060A92;
    gfloat32 b = decode_float( a );
    emscripten_log( EM_LOG_CONSOLE, "Decoded float b: %g", b );
    gfloat32 c = sinf( b );
    emscripten_log( EM_LOG_CONSOLE, "sinf(b): %g", c );
}
```

Results:

```
dannii@ub1510:~$ emcc -s WASM=1 -s EMTERPRETIFY=1 -s EMTERPRETIFY_ASYNC=1 -s EMTERPRETIFY_WHITELIST='["_main"]' -O3 sinftest.c
dannii@ub1510:~$ node a.out.js
Decoded float b: 0.523599
sinf(b): 0.5
dannii@ub1510:~$ emcc -s WASM=1 -s EMTERPRETIFY=1 -s EMTERPRETIFY_ASYNC=1 -s EMTERPRETIFY_WHITELIST='["_main"]' -O0 sinftest.c
dannii@ub1510:~$ node a.out.js
Decoded float b: 0.523599
sinf(b): 0

```

Something funny is also going on that the values aren't being passed to functions properly.

```
#include "emscripten.h"
#include <stdint.h>
#include <math.h>

typedef uint32_t glui32;
typedef float gfloat32;

gfloat32 decode_float(glui32 val);
int test_feq( glui32 val );

gfloat32 decode_float(glui32 val)
{
    gfloat32 res;
    *(glui32 *)(&res) = val;
    return res;
}


int test_feq( glui32 val )
{
    emscripten_log( EM_LOG_CONSOLE, "test_feq(): val: %g", decode_float( val ) );
    return 0;
}

int main(void)
{
    emscripten_sleep(10);
    emscripten_log( EM_LOG_CONSOLE, "val: %g", decode_float( 0x3F000000 ) );
    test_feq( 0x3F000000 );
}
```

```
dannii@ub1510:~$ emcc -s WASM=1 -s EMTERPRETIFY=1 -s EMTERPRETIFY_ASYNC=1 -s EMTERPRETIFY_WHITELIST='["_main"]' -O0 sinftest2.c
dannii@ub1510:~$ node a.out.js
val: 0.5
test_feq(): val: 0
```

---

[kripken]: Thanks! Good find, and good testcase.

Turns out the bug was in handling of float (not double) calls in emterpreter-async mode + assertions. Such a specific combination, we didn't notice before... This isn't actually wasm-related, actually, but wasm does turn on PRECISE_F32 by default, which is why this was noticeable there. Fix in #6431

---

[curiousdannii]: Ah, funny how these combinations of features can turn out to be surprisingly rare. Good to know WASM mode hasn't got a deep bug somewhere!

Thank you for the quick diagnosis and fix!

---

[kripken]: Fixed by that PR landing.

body:
I'm trying to port an application without touching the main loop.

I'm adding emscripten_wait support to the SDL2 port this way:
```
diff --git a/src/timer/unix/SDL_systimer.c b/src/timer/unix/SDL_systimer.c
index 217fe327f..5d0337d0a 100644
--- a/src/timer/unix/SDL_systimer.c
+++ b/src/timer/unix/SDL_systimer.c
@@ -30,6 +30,8 @@
 #include "SDL_timer.h"
 #include "SDL_assert.h"

+#include <emscripten.h>
+
 /* The clock_gettime provides monotonous time, so we should use it if
    it's available. The clock_gettime function is behind ifdef
    for __USE_POSIX199309
@@ -186,6 +188,9 @@ SDL_GetPerformanceFrequency(void)
 void
 SDL_Delay(Uint32 ms)
 {
+#ifdef __EMSCRIPTEN__
+    emscripten_sleep(ms);
+#else
     int was_error;

 #if HAVE_NANOSLEEP
@@ -224,6 +229,7 @@ SDL_Delay(Uint32 ms)
         was_error = select(0, NULL, NULL, NULL, &tv);
 #endif /* HAVE_NANOSLEEP */
     } while (was_error && (errno == EINTR));
+#endif /* __EMSCRIPTEN__ */
 }

 #endif /* SDL_TIMER_UNIX */
```

and I'm compiling the "cube" example from the tutorial, modified for SDL2:
```
#include <stdio.h>
#include <SDL2/SDL.h>

void dummy(void) { printf("testing EMTERPRETIFY_BLACKLIST\n"); }

int main(int argc, char** argv) {
  SDL_Init(SDL_INIT_VIDEO);
  SDL_Window *sdlWindow = SDL_CreateWindow("test",
					   SDL_WINDOWPOS_UNDEFINED,
					   SDL_WINDOWPOS_UNDEFINED,
					   256, 256,
					   0);
  SDL_Renderer *sdlRenderer = SDL_CreateRenderer(sdlWindow, -1, 0);
  SDL_SetRenderDrawColor(sdlRenderer, 0, 0, 0, 255);
  SDL_RenderClear(sdlRenderer);
  SDL_RenderPresent(sdlRenderer);

  SDL_Surface* screen = SDL_CreateRGBSurface(0, 256,256, 32,
					    0x000000ff, 0x0000ff00, 0x00ff0000, 0xff000000);
  SDL_Texture* sdlTexture = SDL_CreateTexture(sdlRenderer,
					      SDL_PIXELFORMAT_ARGB8888,
					      SDL_TEXTUREACCESS_STREAMING,
					      256, 256);

  int count = 0;
  while (1) {
    count++;
    if (SDL_MUSTLOCK(screen)) SDL_LockSurface(screen);
    for (int i = 0; i < 256; i++) {
      for (int j = 0; j < 256; j++) {
	int alpha = 255;
	*((Uint32*)screen->pixels + i * 256 + j) = SDL_MapRGBA(screen->format, i, j, 255-i+count, alpha);
      }
    }
    if (SDL_MUSTLOCK(screen)) SDL_UnlockSurface(screen);

    SDL_UpdateTexture(sdlTexture, NULL, screen->pixels, 256 * sizeof (Uint32));
    SDL_RenderCopy(sdlRenderer, sdlTexture, NULL, NULL);
    SDL_RenderPresent(sdlRenderer);

    SDL_Event ev;
    SDL_WaitEvent(&ev);
    printf("got event\n");
    if (ev.type == SDL_QUIT)
      break;
  }

  printf("you should see a smoothly-colored square - no sharp lines but the square borders!\n");
  printf("and here is some text that should be HTML-friendly: amp: |&| double-quote: |\"| quote: |'| less-than, greater-than, html-like tags: |<cheez></cheez>|\nanother line.\n");

  SDL_Quit();

  dummy();

  return 0;
}
```

Normally -s EMTERPRETIFY should emterpret everything by default. Just to be sure of it, I'm adding a single "dummy" function to add to EMTERPRETIFY_BLACKLIST, though I tested with and without blacklist.

Compilation:
