$ EMCC_LOCAL_PORTS="sdl2=$HOME/workdir/emsource/ports/SDL2-version_13|SDL2-version_13" emcc cube2.bc -o t/index.html -s USE_SDL=2 -s EMTERPRETIFY=1 -s EMTERPRETIFY_ASYNC=1 -s EMTERPRETIFY_FILE=t/index.em -s EMTERPRETIFY_BLACKLIST='["_dummy"]'
